import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"跨位面伦理准则","description":"","frontmatter":{},"headers":[],"relativePath":"zh/0088-跨位面伦理准则.md","filePath":"zh/0088-跨位面伦理准则.md"}'),o={name:"zh/0088-跨位面伦理准则.md"};function l(h,t,i,u,n,q){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="跨位面伦理准则" tabindex="-1">跨位面伦理准则 <a class="header-anchor" href="#跨位面伦理准则" aria-label="Permalink to &quot;跨位面伦理准则&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>88</td></tr><tr><td>所属模块</td><td>跨位面交互与时间规则</td></tr><tr><td>核心关键词</td><td>跨位面伦理、文明自主、不干涉、文化尊重、共生外交</td></tr></tbody></table><h2 id="一、伦理准则的哲学基础" tabindex="-1">一、伦理准则的哲学基础 <a class="header-anchor" href="#一、伦理准则的哲学基础" aria-label="Permalink to &quot;一、伦理准则的哲学基础&quot;">​</a></h2><p>跨位面伦理准则是锚点共生文明在与其他位面文明进行交互时必须遵循的道德规范与行为准则。其哲学基础是&quot;文明主体性&quot;原则——每一个位面的文明，无论其发展水平高低、种族形态如何、社会制度怎样，都拥有不可剥夺的主体性与自主发展权。任何外来文明都不得以任何理由剥夺这种主体性，或将自身的意志强加于其他文明。</p><p>这一哲学基础的确立，与锚点共生文明的&quot;反掠夺&quot;核心理念一脉相承。掠夺式文明的本质特征，就是不承认其他文明的主体性，将其他文明视为可以利用的资源或可以征服的对象。锚点共生文明要真正超越掠夺式文明，就必须在跨位面交互中彻底摒弃这种心态，以平等、尊重、共生的态度对待每一个遇到的文明。</p><p>跨位面伦理准则的效力范围涵盖一切跨位面交互行为，包括但不限于：位面穿梭、跨位面通讯、考古活动、贸易往来、文化交流、技术合作、以及紧急情况下的人道主义干预。任何组织和个人在进行跨位面交互时，都必须遵守本准则的各项规定。</p><h2 id="二、六大伦理原则" tabindex="-1">二、六大伦理原则 <a class="header-anchor" href="#二、六大伦理原则" aria-label="Permalink to &quot;二、六大伦理原则&quot;">​</a></h2><p>跨位面伦理准则由六大基本原则构成，形成一个完整的伦理价值体系：</p><table tabindex="0"><thead><tr><th>原则</th><th>核心内涵</th><th>具体要求</th></tr></thead><tbody><tr><td>文明自主原则</td><td>尊重目标位面文明的自主发展权，不强行干涉其内部事务</td><td>不得强制改变目标文明的社会制度、意识形态与发展道路；不得在目标文明内部培植代理人或傀儡政权</td></tr><tr><td>不干涉原则</td><td>除非目标文明面临灭绝级危机且主动请求援助，否则不进行任何实质性干涉</td><td>不得介入目标文明的内部冲突；不得向目标文明的任何一方提供武器或军事援助；不得操纵目标文明的舆论与政治进程</td></tr><tr><td>文化尊重原则</td><td>尊重目标文明的文化传统、宗教信仰与风俗习惯</td><td>不得对目标文明的文化进行歧视性评价或恶意嘲讽；不得强制推行本位面的文化产品与价值观；不得以&quot;开化&quot;为名进行文化同化</td></tr><tr><td>平等互利原则</td><td>跨位面交往必须建立在平等基础上，确保双方都能从交往中获益</td><td>不得利用技术优势进行不平等贸易；不得掠夺目标文明的资源；技术输出必须考虑目标文明的接受能力与社会影响</td></tr><tr><td>最小影响原则</td><td>跨位面交互应尽可能减少对目标文明的外部影响</td><td>优先采用低接触、低干扰的交互方式；交互活动的范围与强度应严格控制在必要限度内；交互结束后应评估并消除不必要的遗留影响</td></tr><tr><td>可问责原则</td><td>一切跨位面交互行为都必须可追溯、可监督、可问责</td><td>建立完整的交互档案与日志；设立独立的伦理监督机构；对违反伦理准则的行为进行调查与惩处</td></tr></tbody></table><p>六大原则之间存在内在的逻辑关联：文明自主原则是根本价值，不干涉原则是核心要求，文化尊重原则是文化层面的体现，平等互利原则是经济层面的保障，最小影响原则是操作层面的规范，可问责原则是制度层面的约束。六者共同构成了&quot;价值—要求—体现—保障—规范—约束&quot;的完整伦理闭环。</p><h2 id="三、不同交互场景的伦理规范" tabindex="-1">三、不同交互场景的伦理规范 <a class="header-anchor" href="#三、不同交互场景的伦理规范" aria-label="Permalink to &quot;三、不同交互场景的伦理规范&quot;">​</a></h2><h3 id="_3-1-考古场景的伦理规范" tabindex="-1">3.1 考古场景的伦理规范 <a class="header-anchor" href="#_3-1-考古场景的伦理规范" aria-label="Permalink to &quot;3.1 考古场景的伦理规范&quot;">​</a></h3><p>跨位面考古是最常见的交互场景之一，其伦理规范的核心是&quot;不打扰&quot;。考古团队必须严格遵守复制镜+隔离空间+仅回传知识的标准方案，确保考古过程不被目标文明感知。对于仍有活文明存在的位面，考古范围必须严格限定在已废弃的遗迹区域，不得对活文明的居住区进行任何形式的扫描或复制。</p><p>考古发现的知识在回传与发布时，必须尊重目标文明的文化敏感性。如果考古发现涉及目标文明的宗教圣物、祖先遗骸或文化禁忌，相关信息在发布前须经过跨位面伦理委员会的文化敏感性审查，必要时对敏感细节进行模糊化处理。</p><h3 id="_3-2-通讯场景的伦理规范" tabindex="-1">3.2 通讯场景的伦理规范 <a class="header-anchor" href="#_3-2-通讯场景的伦理规范" aria-label="Permalink to &quot;3.2 通讯场景的伦理规范&quot;">​</a></h3><p>跨位面通讯是与目标文明进行直接交流的方式，其伦理规范的核心是&quot;真诚与尊重&quot;。通讯内容必须真实，不得故意提供虚假信息或进行欺骗性宣传；通讯语气必须平等，不得以居高临下的姿态对待发展水平较低的文明；通讯主题必须经过目标文明的同意，不得强行推送本位面的意识形态或宗教信仰。</p><p>首次与一个未知文明建立通讯时，必须遵循&quot;渐进式接触&quot;规范：首先发送中性的数学与物理信号以确认对方的智慧水平与沟通能力，然后在对方回应的基础上逐步扩大交流范围，不得在首次接触时就发送复杂的文化或技术信息。</p><h3 id="_3-3-贸易场景的伦理规范" tabindex="-1">3.3 贸易场景的伦理规范 <a class="header-anchor" href="#_3-3-贸易场景的伦理规范" aria-label="Permalink to &quot;3.3 贸易场景的伦理规范&quot;">​</a></h3><p>跨位面贸易的伦理规范核心是&quot;公平与可持续&quot;。贸易必须建立在双方自愿的基础上，不得利用信息不对称或技术优势进行胁迫性交易；贸易价格必须公允，不得进行掠夺性定价；贸易商品不得包含可能对目标文明造成社会冲击或生态破坏的内容。</p><p>特别需要注意的是，修炼技术与高能武器的跨位面贸易受到最严格的伦理限制。向发展水平较低的文明输出高阶修炼技术，可能导致其社会结构失衡与内部冲突加剧；输出武器则可能直接引发战争。因此，这两类贸易原则上被禁止，仅在极端特殊的情况下经锚点议事会全体会议审批后方可进行。</p><h3 id="_3-4-紧急干预场景的伦理规范" tabindex="-1">3.4 紧急干预场景的伦理规范 <a class="header-anchor" href="#_3-4-紧急干预场景的伦理规范" aria-label="Permalink to &quot;3.4 紧急干预场景的伦理规范&quot;">​</a></h3><p>当目标位面文明面临灭绝级危机（如小行星撞击、超级瘟疫、法则崩溃）时，锚点共生文明可以进行人道主义干预。但即使在这种紧急情况下，也必须遵循以下伦理规范：</p><ul><li>干预前须尽可能获得目标文明的知情同意，如果目标文明因危机而无法做出有效回应，则由跨位面伦理委员会代为做出&quot;推定同意&quot;判断</li><li>干预手段必须选择对目标文明影响最小的方案，优先采用间接干预（如改变小行星轨道）而非直接干预（如直接降临救援）</li><li>干预过程中不得借机获取目标文明的资源或技术</li><li>干预结束后须立即撤离，不得在目标位面留下永久性存在</li><li>事后须向跨位面伦理委员会提交完整的干预报告，接受伦理审查</li></ul><h2 id="四、伦理监督与违规处理" tabindex="-1">四、伦理监督与违规处理 <a class="header-anchor" href="#四、伦理监督与违规处理" aria-label="Permalink to &quot;四、伦理监督与违规处理&quot;">​</a></h2><p>衡元宙设立&quot;跨位面伦理委员会&quot;作为独立的伦理监督机构，负责制定和解释跨位面伦理准则、审批高风险跨位面交互项目、受理伦理违规投诉、以及对违规行为进行调查与裁决。委员会由来自不同种族、不同专业背景的伦理学家、法学家、科学家与文明代表组成，确保决策的多元性与公正性。</p><p>违反跨位面伦理准则的行为，根据情节轻重，处理措施包括：口头警告、书面谴责、暂停跨位面交互资格、吊销穿梭许可、罚款、监禁刑、以及在极端情况下的&quot;位面放逐&quot;（剥夺在衡元宙主要位面的居住权）。所有伦理违规处理结果均记入个人或组织的伦理档案，永久保存。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>跨位面伦理准则是锚点共生文明道德高度的集中体现。它不仅规定了&quot;不能做什么&quot;，更昭示了&quot;应当成为什么&quot;——一个真正伟大的文明，不是征服了多少其他文明，而是尊重了多少其他文明的主体性。在衡元宙走向星际共生的道路上，跨位面伦理准则将始终是指引方向的道德灯塔。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>0081-位面穿梭规则</li><li>0087-仅回传知识原则</li><li>0004-反掠夺主义核心论纲</li></ul>',30)])])}const _=a(o,[["render",l]]);export{s as __pageData,_ as default};
